import{_ as i,o as a,c as e,a3 as n}from"./chunks/framework.DAK02U1-.js";const k=JSON.parse('{"title":"索引","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"索引 | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/zh/clice/guide/indexing"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"zh_CN"}],["link",{"rel":"canonical","href":"https://docs.clice.io/zh/clice/guide/indexing"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/clice/guide/indexing"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/clice/guide/indexing"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/clice/guide/indexing"}]]},"headers":[],"relativePath":"zh/clice/guide/indexing.md","filePath":"zh/clice/guide/indexing.md","lastUpdated":1794682313000}'),t={name:"zh/clice/guide/indexing.md"};function l(p,s,h,d,o,c){return a(),e("div",null,[...s[0]||(s[0]=[n(`<h1 id="索引" tabindex="-1">索引 <a class="header-anchor" href="#索引" aria-label="Permalink to &quot;索引&quot;">​</a></h1><p>超出已打开文件范围的答案——查找引用、调用层次结构与类型层次结构、工作区符号、重命名，以及在尚未编译的文件上的悬停或导航——都来自 clice 为项目建立的索引。本页介绍索引包含哪些内容，以及如何缩短大型项目首次建立索引的时间。</p><h2 id="索引包含哪些内容" tabindex="-1">索引包含哪些内容 <a class="header-anchor" href="#索引包含哪些内容" aria-label="Permalink to &quot;索引包含哪些内容&quot;">​</a></h2><p>服务器启动时，后台索引会编译项目中的每个翻译单元：编译数据库中的每个文件、规则的 <code>default_command</code> 覆盖的源文件，以及之前打开过、却没有任何数据库列出的文件。它会等你空闲 <code>background_delay_ms</code> 之后才开始，在后台 worker 上运行，并为你正在处理的文件的请求让路。头文件通过包含它的翻译单元建立索引，每种包含方式各索引一次，因此被不同源文件以不同方式编译的头文件，能针对其中每个上下文给出答案。</p><p>索引为每个文件记录它的声明、定义和引用，谁调用了谁，谁派生自谁，以及各翻译单元产生的模板实例化。在函数体内部，索引记录函数体用到的名字，除非 <code>index_function_body</code> 把该文件的函数体排除在外：默认情况下，系统头文件（标准库、<code>-isystem</code> 目录）的函数体会被排除，在那里编写的模板的实例化也一样。系统头文件的其余部分——声明、类型、模板——都会建立索引。</p><p>索引保存在缓存目录中。下一次启动的服务器或下一次 <code>clice index</code> 运行会加载它，只重新编译此后文件发生了变化的翻译单元。<code>clice index</code> 在命令行中构建或更新索引；如果有服务器正在服务该项目，它会请那个服务器来完成。</p><h2 id="加快首次索引" tabindex="-1">加快首次索引 <a class="header-anchor" href="#加快首次索引" aria-label="Permalink to &quot;加快首次索引&quot;">​</a></h2><p>大型项目的首次索引要把每个翻译单元都编译一遍。有三种办法可以缩短它：</p><ul><li><strong>更多 worker。</strong> <code>[workers] background</code> 是同时编译的翻译单元数量：默认为机器物理核心数的一半。如果机器核心多、内存也有富余，就调高它。</li><li><strong>更少的翻译单元。</strong> 设置了 <code>background_index = false</code> 的规则，会让它匹配的文件不作为独立的翻译单元编译：适用于你不会在其中导航的测试、示例、基准测试或生成的源文件。它们包含的头文件仍会通过包含它的其他翻译单元建立索引。</li><li><strong>跳过函数体。</strong> 设置了 <code>skip_function_body = true</code> 的规则，会让除文件自身的编译之外的每次编译都跳过它所匹配文件中的函数体（包括模板），编辑器和后台索引都是如此。把它用在第三方代码上：项目中的翻译单元就只解析它们所包含的库的声明，它们导入的库模块在构建时也会跳过函数体。转发实参的函数模板（如 <code>std::make_unique</code>）仍会解析，编译器需要的 <code>constexpr</code> 函数和返回 <code>auto</code> 的函数也一样。</li></ul><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rules</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">patterns = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;third_party/**&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;external/**&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">skip_function_body = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">background_index = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">lint = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">format = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rules</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">patterns = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;benchmarks/**&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">background_index = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">workers</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">background = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">16</span></span></code></pre></div><p>跳过的代价：这些函数体中的错误不会报告，你的代码实例化其模板时引发的错误也不会报告，函数体用到的名字也不会建立索引——查找引用和调用层次结构止步于它们的声明。<code>skip_function_body = false</code> 在所有地方关闭跳过，包括编辑器自身的编译：默认情况下，编辑器跳过打开文件顶部所包含头文件中的函数体，由后台索引解析它们，并把在其中发现的问题报告在该文件上。</p><h2 id="库的内部实现" tabindex="-1">库的内部实现 <a class="header-anchor" href="#库的内部实现" aria-label="Permalink to &quot;库的内部实现&quot;">​</a></h2><p>要在标准库或其他系统库内部导航——查找库中某个函数的调用者，或其模板的实例化——就让一条规则为它的函数体建立索引：</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rules</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">patterns = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/usr/include/c++/**&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">index_function_body = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><p>索引每多记录一个函数体就会变大一些，因此最好只对你会阅读的库这样做。</p>`,15)])])}const g=i(t,[["render",l]]);export{k as __pageData,g as default};
